def expand(steps, table):
    header, *rows = table
    scenarios = []
    for row in rows:
        values = dict(zip(header, row))
        scenario = []
        for step in steps:
            for name, value in values.items():
                step = step.replace(f'<{name}>', value)
            scenario.append(step)
        scenarios.append(scenario)
    return scenarios

function matchStep(expression, text) {
  const types = [];
  const parts = expression.split(/(\{int\}|\{string\})/);
  let pattern = '^';
  for (const part of parts) {
    if (part === '{int}') { pattern += '(-?\\d+)'; types.push('int'); }
    else if (part === '{string}') { pattern += '"([^"]*)"'; types.push('string'); }
    else pattern += part.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  }
  const m = new RegExp(pattern + '$').exec(text);
  if (!m) return null;
  return types.map((t, i) => (t === 'int' ? Number(m[i + 1]) : m[i + 1]));
}
